<script setup lang="ts">
import { ref, watch } from 'vue'
import type { UserInfo } from '../api'
import { useAdminPage } from '../admin-page'
import { getRequests, resolveRequest, requestStatuses, choices, dateTime, type ResourceRequest, type Demand } from '../growth'
import PublishedPaperPicker from './PublishedPaperPicker.vue'
const props = defineProps<{ user: UserInfo }>()
const items = ref<ResourceRequest[]>([]), demand = ref<Demand[]>([]), total = ref(0), pageNumber = ref(1), status = ref('pending'), fingerprint = ref(''), target = ref<ResourceRequest | null>(null), dialog = ref(false)
const page = useAdminPage(async valid => { const result = await getRequests(status.value === 'all' ? '' : status.value, fingerprint.value, (pageNumber.value - 1) * 20); if (valid()) { items.value = result.items; total.value = result.total; demand.value = result.demand } }, () => { dialog.value = false })
const { error, notice, loading, busy } = page
watch(pageNumber, page.load)
watch([status, fingerprint], () => { if (pageNumber.value === 1) void page.load(); else pageNumber.value = 1 })
function edit(item: ResourceRequest) { target.value = { ...item }; error.value = ''; dialog.value = true }
function filter(item: Demand) { status.value = 'all'; fingerprint.value = item.fingerprint }
function save() { if (!target.value) return; void page.act(async valid => { await resolveRequest(props.user.id, { ...target.value!, catalog_id: target.value!.status === 'fulfilled' ? target.value!.catalog_id : null }); if (valid()) { dialog.value = false; notice.value = '需求处理结果已保存，并同步到用户消息中心'; await page.load() } }) }
</script>
<template>
  <section class="admin-section"><p class="text-sm text-muted mb-4">查看用户缺少哪些资料，安排制作并关联补齐结果。同名、同年级和同学科的待处理需求会自动汇总。</p><UAlert v-if="error" :title="error" color="error" class="notice" /><UAlert v-if="notice" :title="notice" color="success" class="notice" />
    <div v-if="demand.length" class="demand-grid"><button v-for="item in demand.slice(0, 12)" :key="item.fingerprint" class="demand-card" :class="{ selected: fingerprint === item.fingerprint }" :disabled="loading" @click="filter(item)"><strong>{{ item.title }}</strong><span>{{ item.grade || '不限年级' }} · {{ item.subject || '不限学科' }}</span><b>{{ item.users }} 人需要 · {{ item.requests }} 条待处理</b></button></div><p v-if="demand.length > 12" class="text-sm text-muted mb-3">展示需求最多的前 12 项，完整请求可在下方按状态查看。</p>
    <div class="section-toolbar"><div class="actions-row"><USelect v-model="status" :items="[{ value: 'all', label: '全部状态' }, ...choices(requestStatuses)]" :disabled="loading" aria-label="资料需求状态" /><UButton v-if="fingerprint" label="清除需求筛选" variant="outline" :disabled="loading" @click="fingerprint = ''" /></div><UButton label="刷新" :loading="loading" variant="outline" @click="page.load" /></div>
    <div class="data-scroll"><table class="data-table"><thead><tr><th>资料需求</th><th>用户</th><th>年级 / 学科</th><th>状态</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td class="name-cell">{{ item.title }}</td><td>{{ item.nickname || item.username }}</td><td>{{ item.grade || '不限' }} / {{ item.subject || '不限' }}</td><td>{{ requestStatuses[item.status] }}</td><td>{{ dateTime(item.updated_at) }}</td><td><UButton label="处理需求" variant="soft" @click="edit(item)" /></td></tr><tr v-if="!items.length"><td colspan="6">{{ loading ? '正在加载' : '暂无匹配的资料需求' }}</td></tr></tbody></table></div><div class="table-footer"><span>共 {{ total }} 条需求</span><UPagination v-if="total > 20" v-model:page="pageNumber" :total="total" :items-per-page="20" :disabled="loading" /></div>
    <UModal v-model:open="dialog" title="处理资料需求" :dismissible="!busy" :close="!busy" :ui="{ content: 'max-w-2xl' }"><template #body><form v-if="target" id="resource-resolution" class="field-stack" @submit.prevent="save"><div><h3 class="font-semibold">{{ target.title }}</h3><p class="text-sm text-muted mt-2">{{ target.nickname || target.username }} · {{ target.grade }} · {{ target.subject }}</p><p class="original-details">{{ target.details || '用户未补充说明' }}</p></div><UFormField label="处理状态"><USelect v-model="target.status" :items="choices(requestStatuses)" :disabled="busy" class="w-full" /></UFormField><UFormField label="回复用户"><UTextarea v-model="target.reply" :disabled="busy" maxlength="1000" :rows="4" class="w-full" placeholder="说明安排或资料使用建议" /></UFormField><UFormField v-if="target.status === 'fulfilled'" label="关联补齐的已发布资料" required><PublishedPaperPicker v-model="target.catalog_id" :label="target.paper_title" :disabled="busy" @selected="target.paper_title = $event.title" /></UFormField><UAlert v-if="error" :title="error" color="error" /></form></template><template #footer><UButton label="取消" variant="outline" color="neutral" :disabled="busy" @click="dialog = false" /><UButton label="保存处理结果" type="submit" form="resource-resolution" :loading="busy" :disabled="busy || (target?.status === 'fulfilled' && !target.catalog_id)" /></template></UModal>
  </section>
</template>
<style scoped>.demand-grid { display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px;margin-bottom:24px; }.demand-card { display:flex;flex-direction:column;gap:8px;padding:16px;border:1px solid var(--ui-border);border-radius:10px;text-align:left;font-size:13px;overflow-wrap:anywhere; }.demand-card span { font-size:12px;color:var(--ui-text-muted); }.demand-card b { font-weight:500;color:var(--ui-primary); }.demand-card.selected { border-color:var(--ui-primary); }.original-details { margin-top:12px;white-space:pre-wrap;line-height:1.8;font-size:14px; }</style>
